function detectLicense(root) {
  for (const n of ["LICENSE", "LICENSE.md", "LICENSE.txt", "COPYING", "UNLICENSE"]) {
    const p = path.join(root, n);
    if (!fs.existsSync(p)) continue;
    const t = fs.readFileSync(p, "utf8").slice(0, 6000);
