function isNullOrUndefined(scope, node) {
	return (
		isNullLiteral(node) ||
		(node.type === "Identifier" &&
			node.name === "undefined" &&
			isReferenceToGlobalVariable(scope, node)) ||
		(node.type === "UnaryExpression" && node.operator === "void")
	);
