function isStaticLiteral(scope, node) {
	switch (node.type) {
		case "Literal":
			return true;
		case "UnaryExpression":
			return (
				["-", "+", "~"].includes(node.operator) &&
				node.argument.type === "Literal"
			);
		case "Identifier":
			return (
				node.name === "undefined" &&
				isReferenceToGlobalVariable(scope, node)
			);
		case "TemplateLiteral":
			return node.expressions.length === 0;
		default:
			return false;
	}
}
