/** Asks the FastifyAdapter to register the `@fastify/multipart` plugin (it skips that when the plugin is registered already, or when its `multipart` option is `false`), and fails the application's startup with an actionable message if the plugin still is not registered once every plugin has loaded. Without the plugin, Fastify answers every multipart request with a bare 415 before any interceptor runs. This runs from `onModuleInit`, before Fastify's `ready()`: the plugin registered here loads with the others, before the server starts, and the check is deferred to an `onReady` hook. */
function setUpHttpAdapter(adapterHost: HttpAdapterHost | undefined) {
  const httpAdapter = adapterHost?.httpAdapter;
  if (!httpAdapter) {
    return;
  }
  if (httpAdapter.getType() !== 'fastify') {
    throw new Error(WRONG_ADAPTER_MESSAGE);
  }
  const instance = httpAdapter.getInstance<FastifyInstance>();
  if (verifiedInstances.has(instance)) {
    return;
  }
  const isRegistered = () => instance.hasRequestDecorator('isMultipart');
  try {
    (httpAdapter as unknown as Partial<FastifyAdapter>).useMultipart?.();
    instance.addHook('onReady', async () => {
      if (!isRegistered()) {
        throw new Error(MISSING_PLUGIN_MESSAGE);
      }
    });
  } catch {
    // The instance has already started (e.g. the interceptor was created
    // by a lazy-loaded module): no plugin can be registered any more, and
    // every plugin is loaded.
    if (!isRegistered()) {
      throw new Error(PLUGIN_NOT_REGISTERED_AT_STARTUP_MESSAGE);
    }
  }
  verifiedInstances.add(instance);
}
