/** Ends a pool once its connections have closed: `pool.end()` resolves before they have, so a database dropped right after (`WITH (FORCE)`, as support/postgres.ts does) could terminate one, an error nothing listens for. */
export async function endPool(pool: pg.Pool): Promise<void> {
  let open = pool.totalCount;
  const closed = new Promise<void>(resolve => {
    if (open === 0) return resolve();
    pool.on('remove', () => {
      if (--open === 0) resolve();
    });
  });
  await pool.end();
  await closed;
}
